import XCTest
@testable import GymSync

/// The generator grid harness (owner 2026-08-15: "generate every
/// conceivable combination… adversarially inspect"): runs the REAL
/// generate() over the structural input grid against a PRODUCTION
/// catalog snapshot and prints one JSON line per program, prefixed
/// GRIDJSON| — CI's build-test log becomes the corpus the trainer-swarm
/// audit reviews. Deliberately never a reimplementation: what the swarm
/// reads is exactly what the app ships. Doubles as a permanent
/// regression harness — the grid must always generate cleanly.
final class GeneratorGridDumpTests: XCTestCase {

    private struct CatalogRow: Decodable {
        let name: String
        let primary_muscle: String
        let category: String
        let equipment: String
        let movement_pattern: String
    }

    private func loadCatalog() throws -> [ProgramGenerator.CatalogExercise] {
        let rows = try JSONDecoder().decode([CatalogRow].self,
                                            from: Self.catalogJSON.data(using: .utf8)!)
        return rows.enumerated().map { index, row in
            ProgramGenerator.CatalogExercise(
                id: UUID(uuidString: String(format: "00000000-0000-0000-0001-%012d", index))!,
                name: row.name, primaryMuscle: row.primary_muscle,
                secondaryMuscles: [], category: row.category,
                equipment: row.equipment, movementPattern: row.movement_pattern,
                rank: index)
        }
    }

    func testDumpGrid() throws {
        let catalog = try loadCatalog()
        var id = 0
        func dump(_ label: String, _ inputs: ProgramGenerator.Inputs) {
            id += 1
            let program = ProgramGenerator.generate(inputs: inputs, catalog: catalog)
            var days: [[String: Any]] = []
            for day in program.days {
                let exs: [[String: Any]] = day.exercises.map { ex in
                    var d: [String: Any] = ["x": ex.name, "s": ex.sets,
                                            "r": "\(ex.repsLow)-\(ex.repsHigh)",
                                            "rest": ex.restSeconds, "m": ex.isMain]
                    if let z = ex.cardioZone { d["zone"] = z; d["min"] = ex.cardioMinutes ?? 0 }
                    if let p = ex.percentOfMax { d["pct"] = p }
                    return d
                }
                days.append(["n": day.name, "ex": exs])
            }
            let obj: [String: Any] = [
                "id": id, "label": label,
                "in": ["focus": inputs.focus.rawValue, "days": inputs.daysPerWeek,
                       "weeks": inputs.durationWeeks, "exp": inputs.experience.rawValue,
                       "equip": inputs.equipment.map { Array($0).sorted() } ?? ["all"],
                       "cardioDays": inputs.cardioDays, "cardioMin": inputs.cardioMinutes,
                       "cap": inputs.sessionMinutes ?? 0, "fill": inputs.fillWeekWithRecovery,
                       "seed": inputs.seed] as [String: Any],
                "days": days, "notes": program.notes]
            let data = try! JSONSerialization.data(withJSONObject: obj)
            print("GRIDJSON|" + String(data: data, encoding: .utf8)!)
        }

        let focuses: [GeneratorScience.Focus] = [.strength, .hypertrophy, .weightLoss, .conditioning]
        let experiences: [GeneratorScience.Experience] = [.new, .intermediate, .advanced]
        for f in focuses { for d in 1...7 { for e in experiences {
            dump("core", ProgramGenerator.Inputs(focus: f, daysPerWeek: d, durationWeeks: 8, experience: e))
        } } }
        for f in focuses { for d in 1...7 {
            var i = ProgramGenerator.Inputs(focus: f, daysPerWeek: d, durationWeeks: 8, experience: .intermediate)
            i.equipment = ["machine", "cable", "dumbbell", "bodyweight"]
            dump("no-barbell", i)
        } }
        for f in focuses { for d in 1...7 {
            var i = ProgramGenerator.Inputs(focus: f, daysPerWeek: d, durationWeeks: 8, experience: .intermediate)
            i.sessionMinutes = 60
            dump("cap-60", i)
        } }
        for f in [GeneratorScience.Focus.weightLoss, .conditioning] { for d in 1...7 {
            var i = ProgramGenerator.Inputs(focus: f, daysPerWeek: d, durationWeeks: 8, experience: .intermediate)
            i.cardioDays = 3
            i.cardioMinutes = 30
            dump("cardio-3", i)
        } }
        for f in focuses {
            var i = ProgramGenerator.Inputs(focus: f, daysPerWeek: 5, durationWeeks: 8, experience: .intermediate)
            i.fillWeekWithRecovery = true
            dump("fill-week", i)
        }
        for f in [GeneratorScience.Focus.strength, .hypertrophy] { for d in [3, 4] {
            var i = ProgramGenerator.Inputs(focus: f, daysPerWeek: d, durationWeeks: 8, experience: .intermediate)
            i.seed = 1
            dump("seed-1", i)
        } }
        XCTAssertEqual(id, 162, "the audited grid is the whole structural input space")
    }

